using System.ComponentModel.DataAnnotations;
namespace Grigorova_Server.Models { public class Borrowings { [Key] public int BorrowId { get; set; } public int UserId { get; set; } public int BookId { get; set; } [Display(Name = "Data Start Reading")][DataType(DataType.Date)] public DateTime StartReading { get; set; } [Display(Name = "Data End Reading")][DataType(DataType.Date)] public DateTime? EndReading { get; set; } private string status = "Читается"; [Required] public string BorrowStatus { get => status; set { if (value != "Читается" && value != "Закончена") throw new ArgumentException("Роль должна быть *Читается* или *Закончена*"); status = value; if (status == "Читается") EndReading = null; } } } }